CREATE OR REPLACE VIEW public.errors_wrong_artist_usa_origin
AS SELECT id,
    artist_name,
    origin
   FROM artists
  WHERE (origin::text ~~ '%US%'::text OR origin::text ~~ '%United State%'::text OR origin::text ~~ '%U.S.%'::text) AND (origin::text <> ALL (ARRAY['Alabama, USA'::character varying, 'Alaska, USA'::character varying, 'Arizona, USA'::character varying, 'Arkansas, USA'::character varying, 'California, USA'::character varying, 'Colorado, USA'::character varying, 'Connecticut, USA'::character varying, 'Delaware, USA'::character varying, 'Florida, USA'::character varying, 'Georgia, USA'::character varying, 'Hawaii, USA'::character varying, 'Idaho, USA'::character varying, 'Illinois, USA'::character varying, 'Indiana, USA'::character varying, 'Iowa, USA'::character varying, 'Kansas, USA'::character varying, 'Kentucky, USA'::character varying, 'Louisiana, USA'::character varying, 'Maine, USA'::character varying, 'Maryland, USA'::character varying, 'Massachusetts, USA'::character varying, 'Michigan, USA'::character varying, 'Minnesota, USA'::character varying, 'Mississippi, USA'::character varying, 'Missouri, USA'::character varying, 'Montana, USA'::character varying, 'Nebraska, USA'::character varying, 'Nevada, USA'::character varying, 'New Hampshire, USA'::character varying, 'New Jersey, USA'::character varying, 'New Mexico, USA'::character varying, 'New York, USA'::character varying, 'North Carolina, USA'::character varying, 'North Dakota, USA'::character varying, 'Ohio, USA'::character varying, 'Oklahoma, USA'::character varying, 'Oregon, USA'::character varying, 'Pennsylvania, USA'::character varying, 'Rhode Island, USA'::character varying, 'South Carolina, USA'::character varying, 'South Dakota, USA'::character varying, 'Tennessee, USA'::character varying, 'Texas, USA'::character varying, 'Utah, USA'::character varying, 'Vermont, USA'::character varying, 'Virginia, USA'::character varying, 'Washington, USA'::character varying, 'West Virginia, USA'::character varying, 'Wisconsin, USA'::character varying, 'Wyoming, USA'::character varying]::text[]))
  ORDER BY artist_name;